source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    motifs = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != 2:
                continue
            if all(grid[rr][cc] == 3 for rr, cc in (
                (r-1,c-1),(r-1,c),(r-1,c+1),
                (r,c-1),(r,c+1),
                (r+1,c-1),(r+1,c),(r+1,c+1))):
                motifs.append((r,c))
    for r,c in motifs:
        horizontal_separator = sum(v == 2 for v in grid[r]) >= w * 0.5
        vertical_separator = sum(grid[rr][c] == 2 for rr in range(h)) >= h * 0.5
        if horizontal_separator and not vertical_separator:
            # A horizontal separator sends a ray perpendicular to it.
            for rr in range(h):
                if out[rr][c] == 0:
                    out[rr][c] = 1
            separators = [rr for rr in range(h) if sum(v == 2 for v in grid[rr]) >= w * 0.5]
            for rr in separators:
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        y,x=rr+dr,c+dc
                        if 0 <= y < h and 0 <= x < w and out[y][x] == 0:
                            out[y][x]=1
        elif vertical_separator:
            for cc in range(w):
                if out[r][cc] == 0:
                    out[r][cc] = 1
            separators = [cc for cc in range(w) if sum(grid[rr][cc] == 2 for rr in range(h)) >= h * 0.5]
            for cc in separators:
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        y,x=r+dr,cc+dc
                        if 0 <= y < h and 0 <= x < w and out[y][x] == 0:
                            out[y][x]=1
    return out
'''
